@page "/apply"
@rendermode InteractiveServer
@using sv_2e8c9ee66b114aef8a968fb008f7204e.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@* Step Indicator Bar *@
<div class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < CurrentStep)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
        }
    }
</div>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger mt-3">@ErrorMessage</div>
}

@* Step Content *@
<div class="step-content mt-4">
    @switch (CurrentStep)
    {
        case 0:
            @RenderPersonalInfo();
            break;
        case 1:
            @RenderWorkHistory();
            break;
        case 2:
            @RenderReferences();
            break;
        case 3:
            @RenderCoverLetter();
            break;
        case 4:
            @RenderReviewAndSubmit();
            break;
    }
</div>

@* Step 1: Personal Info *@
@{ RenderFragment RenderPersonalInfo() => @<div>
    <h3>Personal Information</h3>
    <div class="mb-3">
        <label class="form-label">Full Name *</label>
        <input type="text" class="form-control" @bind="FullName" />
    </div>
    <div class="mb-3">
        <label class="form-label">Email *</label>
        <input type="email" class="form-control" @bind="Email" />
        @if (!string.IsNullOrEmpty(EmailValidationMessage))
        {
            <div class="text-danger mt-1">@EmailValidationMessage</div>
        }
    </div>
    <div class="mb-3">
        <label class="form-label">Phone *</label>
        <input type="tel" class="form-control" @bind="Phone" />
    </div>
    <div class="mb-3">
        <label class="form-label">Address *</label>
        <textarea class="form-control" @bind="Address" rows="2"></textarea>
    </div>
    <div class="d-flex justify-content-end">
        <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@IsProcessing">
            @if (IsProcessing) { <span>Validating...</span> } else { <span>Next</span> }
        </button>
    </div>
</div>;}

@* Step 2: Work History *@
@{ RenderFragment RenderWorkHistory() => @<div>
    <h3>Work History</h3>
    @for (int i = 0; i < WorkEntries.Count; i++)
    {
        var index = i;
        <div class="card mb-3 p-3">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h5>Position @(index + 1)</h5>
                @if (WorkEntries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                }
            </div>
            <div class="row">
                <div class="col-md-6 mb-3">
                    <label class="form-label">Company Name *</label>
                    <input type="text" class="form-control" value="@WorkEntries[index].Company"
                           @onchange="(e) => UpdateWorkEntry(index, we => we.Company = e.Value?.ToString() ?? string.Empty)" />
                </div>
                <div class="col-md-6 mb-3">
                    <label class="form-label">Job Title *</label>
                    <input type="text" class="form-control" value="@WorkEntries[index].Title"
                           @onchange="(e) => UpdateWorkEntry(index, we => we.Title = e.Value?.ToString() ?? string.Empty)" />
                </div>
            </div>
            <div class="row">
                <div class="col-md-4 mb-3">
                    <label class="form-label">Start Date *</label>
                    <input type="date" class="form-control" value="@WorkEntries[index].StartDate?.ToString("yyyy-MM-dd")"
                           @onchange="(e) => UpdateWorkEntry(index, we => we.StartDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null)" />
                </div>
                <div class="col-md-4 mb-3">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control" value="@WorkEntries[index].EndDate?.ToString("yyyy-MM-dd")"
                           disabled="@WorkEntries[index].IsCurrent"
                           @onchange="(e) => UpdateWorkEntry(index, we => we.EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null)" />
                </div>
                <div class="col-md-4 mb-3 d-flex align-items-end">
                    <div class="form-check">
                        <input type="checkbox" class="form-check-input" id="current-@index" checked="@WorkEntries[index].IsCurrent"
                               @onchange="(e) => UpdateWorkEntry(index, we => { we.IsCurrent = (bool)(e.Value ?? false); if (we.IsCurrent) we.EndDate = null; })" />
                        <label class="form-check-label" for="current-@index">Currently working here</label>
                    </div>
                </div>
            </div>
            <div class="mb-3">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" value="@WorkEntries[index].Description"
                          @onchange="(e) => UpdateWorkEntry(index, we => we.Description = e.Value?.ToString() ?? string.Empty)"></textarea>
            </div>
        </div>
    }
    <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
        <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
    </div>
</div>;}

@* Step 3: References *@
@{ RenderFragment RenderReferences() => @<div>
    <h3>References</h3>
    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <div class="card mb-3 p-3">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h5>Reference @(index + 1)</h5>
                @if (References.Count > 2)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>
            <div class="row">
                <div class="col-md-6 mb-3">
                    <label class="form-label">Name *</label>
                    <input type="text" class="form-control" value="@References[index].Name"
                           @onchange="(e) => UpdateReference(index, r => r.Name = e.Value?.ToString() ?? string.Empty)" />
                </div>
                <div class="col-md-6 mb-3">
                    <label class="form-label">Relationship *</label>
                    <input type="text" class="form-control" value="@References[index].Relationship"
                           @onchange="(e) => UpdateReference(index, r => r.Relationship = e.Value?.ToString() ?? string.Empty)" />
                </div>
            </div>
            <div class="row">
                <div class="col-md-6 mb-3">
                    <label class="form-label">Email *</label>
                    <input type="email" class="form-control" value="@References[index].Email"
                           @onchange="(e) => UpdateReference(index, r => r.Email = e.Value?.ToString() ?? string.Empty)" />
                </div>
                <div class="col-md-6 mb-3">
                    <label class="form-label">Phone *</label>
                    <input type="tel" class="form-control" value="@References[index].Phone"
                           @onchange="(e) => UpdateReference(index, r => r.Phone = e.Value?.ToString() ?? string.Empty)" />
                </div>
            </div>
        </div>
    }
    @if (References.Count < 3)
    {
        <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
    }
    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
        <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
    </div>
</div>;}

@* Step 4: Cover Letter *@
@{ RenderFragment RenderCoverLetter() => @<div>
    <h3>Cover Letter</h3>
    <div class="mb-3">
        <textarea class="form-control" rows="12" maxlength="2000" @bind="CoverLetterText" @bind:event="oninput"></textarea>
        <div class="text-muted mt-1">@CoverLetterText.Length / 2000 characters</div>
    </div>
    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
        <button class="btn btn-primary" @onclick="NextStep">Next</button>
    </div>
</div>;}

@* Step 5: Review & Submit *@
@{ RenderFragment RenderReviewAndSubmit() => @<div>
    @if (IsSubmitted)
    {
        <div class="text-center py-5">
            <h3 class="text-success">✓ Application Submitted Successfully!</h3>
            <p class="lead mt-3">Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you.</p>
        </div>
    }
    else
    {
        <h3>Review & Submit</h3>

        <div class="card mb-3 p-3">
            <div class="d-flex justify-content-between align-items-center">
                <h5>Personal Information</h5>
                <button class="btn btn-link" @onclick="() => GoToStep(0)">Edit</button>
            </div>
            <dl class="row mb-0">
                <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@FullName</dd>
                <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@Email</dd>
                <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@Phone</dd>
                <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@Address</dd>
            </dl>
        </div>

        <div class="card mb-3 p-3">
            <div class="d-flex justify-content-between align-items-center">
                <h5>Work History</h5>
                <button class="btn btn-link" @onclick="() => GoToStep(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="border-bottom pb-2 mb-2">
                    <strong>@entry.Title</strong> at @entry.Company<br />
                    <small class="text-muted">
                        @entry.StartDate?.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                    </small>
                    @if (!string.IsNullOrEmpty(entry.Description))
                    {
                        <p class="mt-1 mb-0">@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="card mb-3 p-3">
            <div class="d-flex justify-content-between align-items-center">
                <h5>References</h5>
                <button class="btn btn-link" @onclick="() => GoToStep(2)">Edit</button>
            </div>
            @foreach (var reference in References)
            {
                <div class="border-bottom pb-2 mb-2">
                    <strong>@reference.Name</strong> (@reference.Relationship)<br />
                    <small>@reference.Email | @reference.Phone</small>
                </div>
            }
        </div>

        <div class="card mb-3 p-3">
            <div class="d-flex justify-content-between align-items-center">
                <h5>Cover Letter</h5>
                <button class="btn btn-link" @onclick="() => GoToStep(3)">Edit</button>
            </div>
            <p style="white-space: pre-wrap;">@CoverLetterText</p>
        </div>

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@IsProcessing">
                @if (IsProcessing) { <span>Submitting...</span> } else { <span>Submit Application</span> }
            </button>
        </div>
    }
